types.verbatim:
/**
 * @brief       POSIX terminal attributes structure.
 * @details     The complete definition is provided by @p <termios.h>.
 */
struct termios;

/**
 * @brief       Terminal window size structure.
 * @details     The complete definition is provided by @p <sys/ioctl.h>.
 */
struct winsize;

objinit.implementation:
self = __ro_objinit_impl(self, vmt);

self->fs     = fs;
self->mode   = mode;

method.implementation:
if ((self->flags & VO_ACCMODE) == VO_WRONLY) {
  return CH_RET_EBADF;
}
if ((n > (SIZE_MAX >> 1)) || ((n != 0U) && (buf == NULL))) {
  return CH_RET_EINVAL;
}
if (n == 0U) {
  return 0;
}

return __vfsfile_read(self, buf, n);

if ((self->flags & VO_ACCMODE) == VO_RDONLY) {
  return CH_RET_EBADF;
}
if ((n > (SIZE_MAX >> 1)) || ((n != 0U) && (buf == NULL))) {
  return CH_RET_EINVAL;
}
if (n == 0U) {
  return 0;
}

return __vfsfile_write(self, buf, n);

function.implementation:
uint64_t base;
int64_t result;

switch (whence) {
case VFS_SEEK_SET:
  base = 0U;
  break;
case VFS_SEEK_CUR:
  base = current;
  break;
case VFS_SEEK_END:
  base = size;
  break;
default:
  return CH_RET_EINVAL;
}
if (base > UINT32_MAX) {
  return CH_RET_EOVERFLOW;
}
result = (int64_t)base + (int64_t)offset;
if (result < 0) {
  return CH_RET_EINVAL;
}
if (result > INT32_MAX) {
  return CH_RET_EOVERFLOW;
}
*target = (vfs_offset_t)result;

return CH_RET_SUCCESS;
